"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { pulseButtonDefaults, type PulseButtonSpecProps } from "../generated/pulse-button.types";
import { cx } from "../utils/cx";
import { MotionStyle, motionVars } from "../utils/motion";

export interface PulseButtonProps extends PulseButtonSpecProps, Omit<ButtonProps, keyof PulseButtonSpecProps> {}

const css = `
@keyframes rdm-pulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--rdm-c,var(--rd-color-action-primary)) 55%,transparent)}
  70%,100%{box-shadow:0 0 0 var(--rdm-r,12px) transparent}}
.rdm-pulse{animation:rdm-pulse var(--rdm-d,2s) ease-out infinite}
.rdm-pulse[data-rdm-paused],.rdm-pulse[data-disabled]{animation-play-state:paused}
`;

/** A button with a soft ring that keeps radiating out, to draw the eye to the one action that matters. Builds on Button. */
export const PulseButton = forwardRef<HTMLButtonElement, PulseButtonProps>(function PulseButton(
  { children, duration = pulseButtonDefaults.duration, color, isPaused = pulseButtonDefaults.isPaused, className, style, ...rest },
  ref,
) {
  return (
    <>
      <MotionStyle css={css} still={{ ".rdm-pulse": "animation:none" }} />
      <Button
        {...rest}
        ref={ref}
        data-rdm-paused={isPaused || undefined}
        className={cx("rdm-pulse", className)}
        style={(values) => ({ ...motionVars({ "--rdm-d": `${duration}s`, "--rdm-c": color }), ...(typeof style === "function" ? style(values) : style) })}
      >
        {children}
      </Button>
    </>
  );
});

// Generated by rdloom codegen from specs/pulse-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const pulseButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const pulseButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button with a soft ring that keeps radiating out, to draw the eye to the one action that matters now. Builds on Button. */
export interface PulseButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Colour of the ring, any CSS colour. Defaults to the action colour.
   */
  color?: string;
  /**
   * Seconds for one pulse.
   * @default 2
   */
  duration?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const pulseButtonDefaults = {
  variant: "primary",
  size: "md",
  duration: 2,
  isPaused: false,
  isDisabled: false,
  isLoading: false,
} as const;

export const pulseButtonMeta = {
  "name": "PulseButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
